    const SECTION_IDS = ['patient', 'brands', 'compare', 'system', 'coverage', 'faq'];

    const sectionToKeyframeMap = [0, 1, 5, 2, 3, 4];

    const keyframes = [
        { gradX: 50, gradY: 50, sizeX: 50, sizeY: 50, color1: '#F4F8FA', color2: '#D0F5F0', color3: '#E8F5D6', stop1: 26.92, stop2: 54.33 },
