        { gradX: 100, gradY: 50, sizeX: 100, sizeY: 261.49, color1: '#D0F5F0', color2: '#D0F5F0', color3: '#E8F5D6', stop1: 0, stop2: 0 }
    ];

    let sectionDataArray = [];
    const gradientLayer = document.getElementById('background');

    function initializeSections() {
        let sections;
        if (typeof SECTION_IDS !== 'undefined' && SECTION_IDS.length > 0) {
            sections = SECTION_IDS.map(id => document.getElementById(id)).filter(Boolean);
        } else {
            sections = Array.from(document.querySelectorAll('section[id]'));
        }

        const newSectionData = [];
        sections.forEach(section => {
            const rect = section.getBoundingClientRect();
            const scrollTop = window.pageYOffset || document.documentElement.scrollTop;
            const sectionTop = rect.top + scrollTop;
            newSectionData.push({
                id: section.id,
                top: sectionTop,
                bottom: sectionTop + rect.height,
                height: rect.height
            });
        });
        return newSectionData;
    }

    function updateSectionDepths() {
        sectionDataArray = initializeSections();
    }

    function interpolateKeyframes(kf1, kf2, t) {
        return {
            gradX: kf1.gradX + (kf2.gradX - kf1.gradX) * t,
            gradY: kf1.gradY + (kf2.gradY - kf1.gradY) * t,
            sizeX: kf1.sizeX + (kf2.sizeX - kf1.sizeX) * t,
            sizeY: kf1.sizeY + (kf2.sizeY - kf1.sizeY) * t,
            color1: interpolateColor(kf1.color1, kf2.color1, t),
            color2: interpolateColor(kf1.color2, kf2.color2, t),
            color3: interpolateColor(kf1.color3, kf2.color3, t),
            stop1: kf1.stop1 + (kf2.stop1 - kf1.stop1) * t,
            stop2: kf1.stop2 + (kf2.stop2 - kf1.stop2) * t
        };
    }

    function interpolateColor(color1, color2, t) {
        const rgb1 = hexToRgb(color1);
        const rgb2 = hexToRgb(color2);
        const r = Math.round(rgb1.r + (rgb2.r - rgb1.r) * t);
        const g = Math.round(rgb1.g + (rgb2.g - rgb1.g) * t);
        const b = Math.round(rgb1.b + (rgb2.b - rgb1.b) * t);
        return `rgb(${r}, ${g}, ${b})`;
    }

    function hexToRgb(hex) {
        const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
        return result ? {
            r: parseInt(result[1], 16),
            g: parseInt(result[2], 16),
            b: parseInt(result[3], 16)
        } : { r: 0, g: 0, b: 0 };
    }

    function getKeyframeValues(progress) {
        progress = Math.max(0, Math.min(1, progress));
        const keyframeProgress = progress * (keyframes.length - 1);
        const lowerIndex = Math.floor(keyframeProgress);
        const upperIndex = Math.min(lowerIndex + 1, keyframes.length - 1);
        const localProgress = keyframeProgress - lowerIndex;
        return interpolateKeyframes(keyframes[lowerIndex], keyframes[upperIndex], localProgress);
    }

    function updateGradientFromScroll() {
        if (sectionDataArray.length === 0) return;

        const viewportCenter = window.scrollY + window.innerHeight / 2;

        let currentSectionIndex = -1;
        let interpolationFactor = 0;

        for (let i = 0; i < sectionDataArray.length; i++) {
            const section = sectionDataArray[i];
            if (viewportCenter >= section.top && viewportCenter <= section.bottom) {
                currentSectionIndex = i;

                const sectionCenter = section.top + section.height / 2;
                const distanceFromCenter = viewportCenter - sectionCenter;
                const halfSectionHeight = section.height / 2;

                if (i < sectionDataArray.length - 1 && distanceFromCenter > 0) {
                    const nextSection = sectionDataArray[i + 1];
                    const transitionZone = Math.min(section.height * 0.3, (nextSection.top - section.bottom) / 2);
                    const transitionStart = sectionCenter + halfSectionHeight - transitionZone;

                    if (viewportCenter > transitionStart) {
                        interpolationFactor = Math.min(1, (viewportCenter - transitionStart) / transitionZone);
                    }
                } else if (i > 0 && distanceFromCenter < 0) {
                    const prevSection = sectionDataArray[i - 1];
                    const transitionZone = Math.min(section.height * 0.3, (section.top - prevSection.bottom) / 2);
                    const transitionStart = sectionCenter - halfSectionHeight + transitionZone;

                    if (viewportCenter < transitionStart) {
                        interpolationFactor = Math.max(0, 1 - (transitionStart - viewportCenter) / transitionZone);
                        currentSectionIndex = i - 1;
                        interpolationFactor = 1 - interpolationFactor;
                    }
                }
                break;
            }
        }

        if (currentSectionIndex === -1 && sectionDataArray.length > 0) {
            if (viewportCenter < sectionDataArray[0].top) {
                currentSectionIndex = 0;
                interpolationFactor = 0;
            } else if (viewportCenter > sectionDataArray[sectionDataArray.length - 1].bottom) {
                currentSectionIndex = sectionDataArray.length - 1;
                interpolationFactor = 0;
            }
        }

        if (currentSectionIndex >= 0) {
            const currentKeyframeIndex = sectionToKeyframeMap[currentSectionIndex] || currentSectionIndex;
            let targetKeyframeProgress = currentKeyframeIndex / (keyframes.length - 1);

            if (interpolationFactor > 0 && currentSectionIndex < sectionDataArray.length - 1) {
                const nextSectionIndex = currentSectionIndex + 1;
                const nextKeyframeIndex = sectionToKeyframeMap[nextSectionIndex] || nextSectionIndex;
                const nextKeyframeProgress = nextKeyframeIndex / (keyframes.length - 1);

                targetKeyframeProgress = targetKeyframeProgress + 
                    (nextKeyframeProgress - targetKeyframeProgress) * interpolationFactor;
            }

            const values = getKeyframeValues(targetKeyframeProgress);

            gradientLayer.style.setProperty('--grad-x', `${values.gradX}%`);
            gradientLayer.style.setProperty('--grad-y', `${values.gradY}%`);
            gradientLayer.style.setProperty('--grad-size-x', `${values.sizeX}%`);
            gradientLayer.style.setProperty('--grad-size-y', `${values.sizeY}%`);
            gradientLayer.style.setProperty('--color-1', values.color1);
            gradientLayer.style.setProperty('--color-2', values.color2);
            gradientLayer.style.setProperty('--color-3', values.color3);
            gradientLayer.style.setProperty('--stop-1', `${values.stop1}%`);
            gradientLayer.style.setProperty('--stop-2', `${values.stop2}%`);
        }
    }

    sectionDataArray = initializeSections();
    updateGradientFromScroll();

    let ticking = false;
    function onScroll() {
        if (!ticking) {
            window.requestAnimationFrame(() => {
                updateGradientFromScroll();
                ticking = false;
            });
            ticking = true;
        }
    }

    window.addEventListener('scroll', onScroll, { passive: true });
    window.addEventListener('resize', () => {
        updateSectionDepths();
        updateGradientFromScroll();
    });
    window.addEventListener('hashchange', () => {
        setTimeout(() => {
            updateSectionDepths();
            updateGradientFromScroll();
        }, 100);
    });
